import { bindings, defineConfig } from "cf/config";

/**
 * Cloudflare Workers configuration (generated by `vinext init`, extended for environments).
 *
 * - Production:  `npm run deploy`           (Vite mode "production")
 * - Preview:     `npm run deploy:preview`   (Vite mode "preview" -> separate Worker "whirlpick-preview")
 *
 * Custom domain: production uses spinwheelge.com by default; set CF_CUSTOM_DOMAIN to override. Cloudflare then creates the DNS record and HTTPS certificate automatically.
 * The domain's zone must already be on your Cloudflare account.
 *
 * Secrets (optional): YOUTUBE_API_KEY powers the YouTube Comment Picker's link loading. Set it with
 *   npx cf workers secrets update   (see docs/DEPLOYMENT.md)
 * It's read via process.env, which `nodejs_compat` populates from Worker secrets and vars.
 */
export default defineConfig(({ mode }) => {
  const isPreview = mode === "preview";
  // Production is served on spinwheelge.com unless CF_CUSTOM_DOMAIN overrides it (CI passes "" when unset).
  const domain = process.env.CF_CUSTOM_DOMAIN || "spinwheelge.com";
  return {
    worker: {
      name: isPreview ? "whirlpick-preview" : "whirlpick",
      entrypoint: "vinext/server/fetch-handler",
      // Must not be newer than the workerd release bundled with the toolchain.
      compatibilityDate: "2026-10-15",
      compatibilityFlags: ["nodejs_compat"],
      // Preview keeps a workers.dev URL; production is served on the custom domain when one is set.
      workersDev: isPreview || !domain,
      ...(!isPreview && domain ? { domains: [domain] } : {}),
      observability: { enabled: true, logs: { enabled: true, headSamplingRate: 0.1 } },
      assets: {
        htmlHandling: "none",
        notFoundHandling: "none",
        runWorkerFirst: ["/*", "!/_next/static/*", "!/*/_next/static/*"],
      },
      env: {
        ASSETS: bindings.assets(),
        SITE_ENV: bindings.text(isPreview ? "preview" : "production"),
      },
    },
  };
});
